import { Audio } from "@remotion/media";
import { AbsoluteFill, Composition, Sequence, staticFile, useCurrentFrame, useVideoConfig } from "remotion";
import { BackgroundMusic } from "./BackgroundMusic";
import { SceneCaptions } from "./SceneCaptions";
import type { SpeechSpan } from "./ducking";

type Word = { text: string; startMs: number; endMs: number };
type Timing = { text: string; voice: string; durationMs: number; words: Word[]; sentences: Word[] };
type AudioMode = "mix" | "voice-only" | "music-only";
type Props = { timings: Timing[]; speech: SpeechSpan[]; audioMode: AudioMode; fixtureVisualOnly: boolean };

function Film({ timings, speech, audioMode, fixtureVisualOnly }: Props) {
  const { fps } = useVideoConfig();
  return (
    <AbsoluteFill style={{ backgroundColor: "#172c35", color: "white", fontFamily: "Arial, sans-serif" }}>
      {!fixtureVisualOnly && audioMode !== "voice-only" && <BackgroundMusic src="music/bg.wav" speech={speech} />}
      {timings.map((timing, index) => (
        <Sequence key={index} from={index * 150} durationInFrames={150}>
          <AbsoluteFill style={{ justifyContent: "center", alignItems: "center", padding: 160, paddingBottom: 340 }}>
            <div style={{ fontSize: 86, lineHeight: 1.25, maxWidth: 1440, textAlign: "center" }}>{timing.text}</div>
          </AbsoluteFill>
          <SceneCaptions words={timing.words} />
          {!fixtureVisualOnly && audioMode !== "music-only" && (
            <Sequence from={10} layout="none">
              <Audio src={staticFile(`voice/scene-0${index + 1}.mp3`)} volume={1.26} />
            </Sequence>
          )}
        </Sequence>
      ))}
    </AbsoluteFill>
  );
}

export const RemotionRoot = () => (
  <Composition
    id="Main" component={Film} width={1920} height={1080} fps={30} durationInFrames={600}
    defaultProps={{ timings: [] as Timing[], speech: [] as SpeechSpan[], audioMode: "mix" as AudioMode, fixtureVisualOnly: false }}
    calculateMetadata={async ({ props, abortSignal }) => {
      const timings: Timing[] = await Promise.all([1, 2, 3, 4].map(async (index) => {
        const response = await fetch(staticFile(`voice/scene-0${index}.words.json`), { signal: abortSignal });
        if (!response.ok) throw new Error(`Missing scene timings: ${index}`);
        return response.json();
      }));
      if (timings.some((timing) => Math.ceil(10 + timing.durationMs / 1000 * 30 + 15) > 150)) {
        throw new Error("Speech does not fit the approved five-second scene; never trim the narration.");
      }
      const speech = timings.flatMap((timing, index) => timing.sentences.map((sentence) => ({
        startMs: (index * 150 + 10) / 30 * 1000 + sentence.startMs,
        endMs: (index * 150 + 10) / 30 * 1000 + sentence.endMs,
      })));
      return { durationInFrames: 600, props: { ...props, timings, speech } };
    }}
  />
);

