import { createTikTokStyleCaptions, type Caption } from "@remotion/captions";
import { useMemo } from "react";
import { useCurrentFrame, useVideoConfig } from "remotion";

type Word = { text: string; startMs: number; endMs: number };

export function SceneCaptions({ words }: { words: Word[] }) {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();
  const timeMs = frame / fps * 1000;
  const { pages } = useMemo(() => {
    const captions: Caption[] = words.map((word, index) => ({
      text: `${index === 0 ? "" : " "}${word.text}`,
      startMs: word.startMs + 10 / fps * 1000,
      endMs: word.endMs + 10 / fps * 1000,
      timestampMs: (word.startMs + word.endMs) / 2 + 10 / fps * 1000,
      confidence: null,
      pageBreakAfter: index % 4 === 3,
    }));
    return createTikTokStyleCaptions({ captions, combineTokensWithinMilliseconds: 1000, breakOnSilenceAfterMilliseconds: 300 });
  }, [words, fps]);
  const page = pages.find((item) => timeMs >= item.startMs && timeMs < item.startMs + item.durationMs);
  if (!page) return null;
  return (
    <div style={{ position: "absolute", bottom: 140, left: 200, right: 200, textAlign: "center", fontSize: 80, lineHeight: 1.25, whiteSpace: "pre", background: "rgba(0,0,0,0.6)", padding: 20, borderRadius: 12 }}>
      {page.tokens.map((token, index) => (
        <span key={`${token.fromMs}-${index}`}>
          {index === 2 ? "\n" : ""}
          <span style={{ visibility: timeMs >= token.fromMs ? "visible" : "hidden", color: timeMs >= token.fromMs && timeMs < token.toMs ? "#ffd675" : "white" }}>
            {token.text}
          </span>
        </span>
      ))}
    </div>
  );
}

